await figma.loadFontAsync({family:"Inter",style:"Medium"});
const s = figma.createSticky();
await figma.loadFontAsync(s.text.fontName);
s.text.characters = "Proposed, under review: free pickup for orders over €100";
s.x = 1552; s.y = 600;
s.name = "Proposal note";
const nodes = figma.currentPage.children.filter(n=>n.id!==s.id && n.type!=="CONNECTOR");
const overlaps = nodes.filter(n => !(n.x+n.width<=s.x || s.x+s.width<=n.x || n.y+n.height<=s.y || s.y+s.height<=n.y)).map(n=>n.name);
return {id:s.id, x:s.x, y:s.y, w:s.width, h:s.height, overlaps};

